function validate([cost]) {
  if (cost.length < 1 || cost.length > 100) return 'cost needs 1 to 100 values.';
  if (cost.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each cost is between 1 and 100.';
  return null;
}

