function minCosts(cost) {
  // Literal model: search every arrangement of the line. You are -1; person k starts at place k.
  const n = cost.length;
  const start = [...Array(n).keys(), -1];
  const best = new Map([[start.join(), 0]]);
  const answer = new Array(n).fill(Infinity);
  // Dijkstra with one bucket per total paid. No answer exceeds 100: place i is reachable directly for cost[i].
  const buckets = Array.from({ length: 101 }, () => []);
  buckets[0].push(start);
  for (let paid = 0; paid <= 100; paid++) {
    for (let b = 0; b < buckets[paid].length; b++) {
      const line = buckets[paid][b];
      if (best.get(line.join()) !== paid) continue;
      const me = line.indexOf(-1);
      if (me < n) answer[me] = Math.min(answer[me], paid);
      for (let j = 0; j <= n; j++) {
        if (j === me) continue;
        const total = paid + (j < me ? cost[line[j]] : 0);
        const next = line.slice();
        next[me] = line[j];
        next[j] = -1;
        const key = next.join();
        if (total <= 100 && !(best.get(key) <= total)) { best.set(key, total); buckets[total].push(next); }
      }
    }
  }
  return answer;
}

