function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(1, 6);
  const shape = rand();
  if (shape < (size === 'large' ? 0.5 : 0.15)) {
    // Prices that keep falling, so the answer changes at many places.
    let price = int(n, 100);
    return [Array.from({ length: n }, () => (price = Math.max(1, price - int(0, 2))))];
  }
  if (shape < (size === 'large' ? 0.6 : 0.25)) {
    const value = int(1, 100);
    return [new Array(n).fill(value)];
  }
  const top = size === 'small' && shape < 0.6 ? 5 : 100;
  return [Array.from({ length: n }, () => int(1, top))];
}
